// ckir_fft_profilee.cu — the Nsight-Compute target for OUR CKIR FFT kernels (generated by crd-kir-tests
// "[.emit-fft-cuda]" into generated/*.cu — regenerate after any ckir_fft.hpp change). Launches each kernel twice
// (warmup + profiled) over the SAME 1024^2 workload cuFFT's vector_fft/regular_fft were profiled on, so ncu reads
// registers/occupancy/stalls/L2 apples-to-apples. Build (match the `precise` semantics: no FMA contraction):
//   nvcc -O3 --fmad=false -allow-unsupported-compiler ckir_fft_profilee.cu -o ckir_fft_profilee.exe
#include <cuda_runtime.h>
#include <cstdio>

#define ckir fft1024_r4_batched
#include "generated/fft1024_r4_batched.cu"
#undef ckir
#define ckir conv1024_fused
#include "generated/conv1024_fused.cu"
#undef ckir
#define ckir transpose1024_t32
#include "generated/transpose1024_t32.cu"
#undef ckir
#define ckir fft1024_r16_batched
#include "generated/fft1024_r16_batched.cu"
#undef ckir
#define ckir conv1024_r16_fused
#include "generated/conv1024_r16_fused.cu"
#undef ckir

int main()
{
    const int n   = 1024;
    const int rc  = n * n;
    float*    ire = nullptr; float* iim = nullptr; // image planes
    float*    ore = nullptr; float* oim = nullptr;
    float*    twr = nullptr; float* twi = nullptr; // W_N[N]
    float*    flr = nullptr; float* fli = nullptr; // filter spectrum (transposed layout)
    cudaMalloc(&ire, sizeof(float) * rc);
    cudaMalloc(&iim, sizeof(float) * rc);
    cudaMalloc(&ore, sizeof(float) * rc);
    cudaMalloc(&oim, sizeof(float) * rc);
    cudaMalloc(&twr, sizeof(float) * n);
    cudaMalloc(&twi, sizeof(float) * n);
    cudaMalloc(&flr, sizeof(float) * rc);
    cudaMalloc(&fli, sizeof(float) * rc);
    cudaMemset(ire, 0, sizeof(float) * rc);
    cudaMemset(iim, 0, sizeof(float) * rc);
    cudaMemset(twr, 0, sizeof(float) * n);
    cudaMemset(twi, 0, sizeof(float) * n);
    cudaMemset(flr, 0, sizeof(float) * rc);
    cudaMemset(fli, 0, sizeof(float) * rc);

    for (int r = 0; r < 2; ++r) // warmup + profiled instance of each
    {
        fft1024_r4_batched<<<1024, 256>>>(ire, iim, twr, twi, ore, oim);        // the batched row FFT (grid=rows)
        conv1024_fused<<<1024, 256>>>(ire, iim, twr, twi, flr, fli, ore, oim);  // the fused column conv (grid=cols)
        transpose1024_t32<<<1024, 1024>>>(ire, ore);                             // the tile-32 coalesced transpose
        fft1024_r16_batched<<<1024, 64>>>(ire, iim, twr, twi, ore, oim);         // REGISTER-BLOCKED radix-16 row FFT
        conv1024_r16_fused<<<1024, 64>>>(ire, iim, twr, twi, flr, fli, ore, oim); // REGISTER-BLOCKED radix-16 fused conv
    }
    cudaDeviceSynchronize();
    const cudaError_t err = cudaGetLastError();
    std::printf("done: %s\n", cudaGetErrorString(err));
    cudaFree(ire); cudaFree(iim); cudaFree(ore); cudaFree(oim);
    cudaFree(twr); cudaFree(twi); cudaFree(flr); cudaFree(fli);
    return err == cudaSuccess ? 0 : 1;
}
